export function Blocker({
  itemName = "{{itemName}}",
  reason = "{{reason}}",
  severity = "{{severity}}",
  owner = "{{owner}}",
  accent = "{{accent}}",
  showOwner = {{showOwner}},
}) {
  const badge = {
    blocking: { text: "Blocking", bg: "#f6d3cd", color: "#8a2c1e" },
    "at-risk": { text: "At risk", bg: "#fbe6bd", color: "#8a5d00" },
    resolved: { text: "Resolved", bg: "#cdeedb", color: "#1a7a4c" },
  }[severity] ?? { text: "Blocking", bg: "#f6d3cd", color: "#8a2c1e" };
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", padding: "16px 18px", borderRadius: 12, maxWidth: 380, boxSizing: "border-box",
      borderLeft: `4px solid ${accent}` }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 700, textTransform: "uppercase",
        letterSpacing: "0.03em", padding: "3px 9px", borderRadius: 999, width: "fit-content", marginBottom: 8,
        background: badge.bg, color: badge.color }}>
        <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
          {severity === "blocking" && <><path d="M8 2.5l6.5 11h-13L8 2.5z" stroke="currentColor" strokeWidth="1.5" strokeLinejoin="round" /><path d="M8 6.5v3.2" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /><circle cx="8" cy="11.6" r=".9" fill="currentColor" /></>}
          {severity === "at-risk" && <><circle cx="8" cy="8" r="6" stroke="currentColor" strokeWidth="1.6" /><path d="M8 5v3.6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" /><circle cx="8" cy="11" r="0.9" fill="currentColor" /></>}
          {severity === "resolved" && <path d="M3 8.5l3 3 7-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />}
        </svg>
        {badge.text}
      </div>
      <h3 style={{ margin: "0 0 4px", fontSize: 16 }}>{itemName} is blocked</h3>
      <p style={{ margin: 0, color: "#241430cc" }}>{reason}</p>
      {showOwner && <p style={{ margin: "10px 0 0", fontSize: 13 }}>Follow up with <strong>{owner}</strong></p>}
    </div>
  );
}
